948	    private startHoloPulsar() {
949	        const canvas = document.getElementById('oracle-hologram-canvas') as HTMLCanvasElement;
950	        if (!canvas) return;
951	        this.holoCtx = canvas.getContext('2d');
952	        if (!this.holoCtx) return;
953	
954	        let frame = 0;
955	        const render = () => {
956	            if (!this.holoCtx) return;
957	            const w = canvas.width;
958	            const h = canvas.height;
959	            this.holoCtx.clearRect(0, 0, w, h);
960	
961	            // Cortana Rings
962	            for (let i = 0; i < 3; i++) {
963	                const radius = (frame * 2 + i * 40) % 150;
964	                const opacity = 1 - (radius / 150);
965	                this.holoCtx.beginPath();
966	                this.holoCtx.arc(w/2, h/2, radius, 0, Math.PI * 2);
967	                this.holoCtx.strokeStyle = `rgba(0, 242, 255, ${opacity * 0.5})`;
968	                this.holoCtx.lineWidth = 2;
969	                this.holoCtx.stroke();
970	            }
971	
972	            // Central Core
973	            const corePulse = Math.sin(frame * 0.1) * 5 + 30;
974	            const grad = this.holoCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, corePulse);
975	            grad.addColorStop(0, 'rgba(0, 242, 255, 0.8)');
976	            grad.addColorStop(1, 'transparent');
977	            this.holoCtx.fillStyle = grad;
978	            this.holoCtx.beginPath();
979	            this.holoCtx.arc(w/2, h/2, corePulse, 0, Math.PI * 2);
980	            this.holoCtx.fill();
981	
982	            frame++;
983	            this.holoAnim = requestAnimationFrame(render);
984	        };
985	        render();
986	    }
